const incoming = $input.first().json;
const input = incoming.body ?? incoming;
if (!input || typeof input !== 'object' || Array.isArray(input)) {
  throw new TypeError('O webhook não recebeu um objeto de evento.');
}
if (
  typeof input.event !== 'string' ||
  typeof input.ticket_id !== 'number' ||
  typeof input.order_id !== 'string' ||
  typeof input.actor !== 'string' ||
  typeof input.updated_at !== 'string' ||
  !Array.isArray(input.triggers) ||
  !Array.isArray(input.logs)
) {
  throw new TypeError('O payload do webhook não contém os campos de auditoria esperados.');
}
const logs = input.logs;
const requests = logs.filter((log) => log.event_type === 'api_request');
const errors = requests.filter((log) => Number(log.status_code) >= 500);
const slowRequests = requests.filter((log) => Number(log.duration_ms) >= 3000);
const countsByActor = new Map();
const countsByRoute = new Map();
for (const log of requests) {
  const actor = log.actor || 'não identificado';
  const route = `${log.method || ''} ${log.path || ''}`.trim() || 'rota não identificada';
  countsByActor.set(actor, (countsByActor.get(actor) || 0) + 1);
  countsByRoute.set(route, (countsByRoute.get(route) || 0) + 1);
}
const frequentActors = [...countsByActor.entries()]
  .filter(([, count]) => count >= 20)
  .map(([actor, count]) => `${actor}: ${count} requisições`);
const checks = [];
if (errors.length >= 3) checks.push(`${errors.length} respostas HTTP 5xx na janela analisada`);
if (slowRequests.length >= 3) checks.push(`${slowRequests.length} requisições com duração igual ou superior a 3 segundos`);
checks.push(...frequentActors.map((actor) => `Volume elevado de um operador (${actor})`));
const relevantLogs = [...errors, ...slowRequests]
  .filter((log, index, all) => all.indexOf(log) === index)
  .slice(0, 8)
  .map((log) => ({ created_at: log.created_at, actor: log.actor, method: log.method, path: log.path, status_code: log.status_code, duration_ms: log.duration_ms }));
const ticketChanges = logs
  .filter((log) => log.event_type === 'ticket_updated')
  .slice(0, 5)
  .map((log) => ({ created_at: log.created_at, actor: log.actor, details: log.details }));
const llmInput = {
  window_minutes: input.logs_window_minutes,
  ticket: {
    id: input.ticket_id,
    order_id: input.order_id,
    actor: input.actor,
    changed_at: input.updated_at,
    triggers: input.triggers,
    lifecycle_status: input.ticket_status,
    order_status: input.order_status,
    priority: input.priority
  },
  request_count: requests.length,
  error_count: errors.length,
  slow_request_count: slowRequests.length,
  frequent_actors: frequentActors,
  busiest_routes: [...countsByRoute.entries()].sort((a, b) => b[1] - a[1]).slice(0, 5).map(([route, count]) => ({ route, count })),
  deterministic_checks: checks,
  anomalous_requests: relevantLogs,
  recent_ticket_changes: ticketChanges
};
return [{ json: { ...input, deterministic_checks: checks, llm_input: llmInput } }];

const base = $('Preparar sinais e janela de logs').first().json;
const response = $input.first().json.response;
if (typeof response !== 'string') {
  throw new TypeError('O Ollama não retornou uma resposta JSON textual.');
}
const assessment = JSON.parse(response);
if (
  typeof assessment.incident_detected !== 'boolean' ||
  !['low', 'medium', 'high'].includes(assessment.severity) ||
  typeof assessment.summary !== 'string' ||
  !Array.isArray(assessment.observations) ||
  !assessment.observations.every((item) => typeof item === 'string')
) {
  throw new TypeError('O LLM retornou um objeto fora do formato esperado.');
}
const incidentDetected = base.deterministic_checks.length > 0 || assessment.incident_detected;
return [{ json: { ...base, incident_detected: incidentDetected, assessment } }];

const d = $input.first().json;
const safeOrderId = String(d.order_id || d.ticket_id).replace(/[^a-zA-Z0-9_-]/g, '_');
const safeTime = String(d.updated_at || new Date().toISOString()).replace(/[:.]/g, '-');
const fileName = `/reports/incidente-${safeOrderId}-${safeTime}.md`;
const observations = [...d.deterministic_checks, ...(d.assessment.observations || [])];
const report = `# Alerta de auditoria Stalse

- **Pedido:** ${d.order_id}
- **Ticket:** ${d.ticket_id}
- **Operador:** ${d.actor || 'Não identificado'}
- **Alterado em:** ${d.updated_at}
- **Status do ticket:** ${d.ticket_status}
- **Status do pedido:** ${d.order_status}
- **Prioridade:** ${d.priority || 'Sem prioridade'}
- **Gatilhos:** ${(d.triggers || []).join(', ')}
- **Severidade sugerida:** ${d.assessment.severity || 'low'}

## Resumo do LLM

${d.assessment.summary}

## Sinais observados

${observations.length ? observations.map((item) => `- ${item}`).join('
') : '- Nenhum limiar determinista foi ultrapassado.'}

## Contexto da janela

${d.logs_window_minutes} minutos; ${d.logs?.length || 0} eventos operacionais anexados.

> A análise automática é indicativa; confirme os eventos e métricas antes de tomar medidas.
`;
return [{ json: { ...d, report_path: fileName }, binary: { data: { data: Buffer.from(report).toString('base64'), mimeType: 'text/markdown', fileName } } }];

